import time

class Deadline:

    def __init__(self, timeout_seconds):

        self.end = (
            time.monotonic()
            + timeout_seconds
        )

    def remaining(self):

        return max(
            0.0,
            self.end - time.monotonic()
        )

    def check(self):

        if self.remaining() <= 0:
            raise TimeoutError(
                "Request deadline exceeded"
            )

